/**
 * createAutocomplete(fetchSuggestions, options)
 * - fetchSuggestions(query) returns a Promise of strings
 * - options: { debounceMs = 300, minLength = 1, maxResults = 8, cacheSize = 50 }
 * Returns { update(text, onResults), cancel(), getState() }.
 * onResults receives { query, status, items, message } for the latest query only.
 */
export default function createAutocomplete(fetchSuggestions, options = {}) {
  const { debounceMs = 300, minLength = 1, maxResults = 8, cacheSize = 50 } = options;
  const cache = new Map();
  let timer = null;
  let latest = '';
  let requestId = 0;
  let state = { query: '', status: 'idle', items: [], message: '' };

  function emit(onResults, next) {
    state = next;
    onResults(next);
  }

  function remember(query, items) {
    cache.delete(query);
    cache.set(query, items);
    if (cache.size > cacheSize) cache.delete(cache.keys().next().value);
  }

  function rank(query, items) {
    const q = query.toLowerCase();
    const seen = new Set();
    const prefix = [];
    const inner = [];
    for (const raw of items) {
      const item = String(raw).trim();
      const key = item.toLowerCase();
      if (!item || seen.has(key)) continue;
      seen.add(key);
      if (key.startsWith(q)) prefix.push(item);
      else if (key.includes(q)) inner.push(item);
    }
    const byName = (a, b) => a.localeCompare(b);
    return [...prefix.sort(byName), ...inner.sort(byName)].slice(0, maxResults);
  }

  function cancel() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
    requestId += 1;
  }

  function update(text, onResults) {
    const query = String(text ?? '').trim().toLowerCase();
    latest = query;
    cancel();
    if (query.length < minLength) {
      emit(onResults, { query, status: 'idle', items: [], message: '' });
      return;
    }
    if (cache.has(query)) {
      emit(onResults, { query, status: 'ready', items: cache.get(query), message: '' });
      return;
    }
    emit(onResults, { query, status: 'waiting', items: state.items, message: '' });
    timer = setTimeout(() => {
      timer = null;
      const id = ++requestId;
      emit(onResults, { query, status: 'loading', items: state.items, message: '' });
      Promise.resolve()
        .then(() => fetchSuggestions(query))
        .then((items) => {
          if (id !== requestId || query !== latest) return;
          const ranked = rank(query, Array.isArray(items) ? items : []);
          remember(query, ranked);
          emit(onResults, { query, status: 'ready', items: ranked, message: '' });
        })
        .catch((error) => {
          if (id !== requestId || query !== latest) return;
          const message = error instanceof Error && error.message ? error.message : 'Suggestions unavailable';
          emit(onResults, { query, status: 'error', items: [], message });
        });
    }, debounceMs);
  }

  return { update, cancel, getState: () => state };
}
